package fixture

import "testing"

func TestWordCount(t *testing.T) {
	if got := WordCount("one two  three"); got != 3 {
		t.Fatalf("WordCount = %d, want 3", got)
	}
	if got := WordCount(""); got != 0 {
		t.Fatalf("WordCount(empty) = %d", got)
	}
}
